/* CommerceForge Dev Docs — Design System */
:root {
  --bg-primary: #0a0e17;
  --bg-secondary: #111620;
  --bg-card: #161b24;
  --bg-card-hover: #1c2330;
  --bg-code: #0d1117;
  --bg-surface: #131720;
  --accent: #475F91;
  --accent-hover: #5B78B0;
  --cta: #00CF8B;
  --cta-hover: #00E5A0;
  --text-primary: #E6EDF3;
  --text-secondary: #8B949E;
  --text-muted: #6E7681;
  --border: #21262D;
  --border-light: #30363D;
  --radius-sm: 6px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --shadow-card: 0 1px 3px rgba(0,0,0,0.3), 0 1px 2px rgba(0,0,0,0.2);
  --shadow-lg: 0 8px 24px rgba(0,0,0,0.4);
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', 'Cascadia Code', 'Consolas', monospace;
  --max-width: 1280px;
  --sidebar-width: 260px;
  --topnav-height: 56px;
  --transition: 200ms ease;
}

* { margin: 0; padding: 0; box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  font-family: var(--font-body);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

/* Top Navigation */
.topnav {
  position: sticky; top: 0; z-index: 100;
  background: rgba(10,14,23,0.85); backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
  height: var(--topnav-height);
  display: flex; align-items: center;
}
.topnav-inner {
  width: 100%; max-width: var(--max-width); margin: 0 auto;
  display: flex; align-items: center; justify-content: space-between;
  padding: 0 24px;
}
.topnav-logo {
  font-weight: 700; font-size: 1.1rem; color: var(--text-primary);
  text-decoration: none; letter-spacing: -0.01em;
  display: flex; align-items: center; gap: 8px;
}
.topnav-logo-icon { width: 28px; height: 28px; border-radius: 6px; background: var(--cta); }
.topnav-links { display: flex; align-items: center; gap: 4px; list-style: none; }
.topnav-links a {
  color: var(--text-secondary); text-decoration: none;
  padding: 6px 14px; border-radius: var(--radius-sm);
  font-size: 0.875rem; font-weight: 500; transition: var(--transition);
}
.topnav-links a:hover, .topnav-links a.active { color: var(--text-primary); background: rgba(255,255,255,0.05); }
.topnav-actions { display: flex; align-items: center; gap: 8px; }
.topnav-search {
  background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius-sm);
  padding: 6px 12px; color: var(--text-muted); font-size: 0.8rem;
  display: flex; align-items: center; gap: 8px; cursor: pointer; transition: var(--transition);
}
.topnav-search:hover { border-color: var(--border-light); color: var(--text-secondary); }
.topnav-search kbd {
  background: var(--bg-primary); border: 1px solid var(--border); border-radius: 3px;
  padding: 1px 5px; font-size: 0.7rem; font-family: var(--font-mono);
}
.dark-toggle {
  background: none; border: 1px solid var(--border); border-radius: var(--radius-sm);
  color: var(--text-secondary); cursor: pointer; padding: 6px 10px; font-size: 0.85rem; transition: var(--transition);
  display: flex; align-items: center; gap: 4px;
}
.dark-toggle:hover { border-color: var(--border-light); color: var(--text-primary); }
.topnav-login {
  background: var(--accent); color: #fff; border: none; border-radius: var(--radius-sm);
  padding: 7px 16px; font-size: 0.8rem; font-weight: 600; cursor: pointer; transition: var(--transition);
  text-decoration: none;
}
.topnav-login:hover { background: var(--accent-hover); }
.mobile-menu-btn {
  display: none; background: none; border: none; color: var(--text-primary); cursor: pointer;
  font-size: 1.3rem; padding: 4px;
}

/* Footer */
.footer {
  background: var(--bg-secondary); border-top: 1px solid var(--border);
  padding: 64px 24px 40px; margin-top: 80px;
}
.footer-grid {
  max-width: var(--max-width); margin: 0 auto;
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 40px;
}
.footer-col h4 { font-size: 0.75rem; text-transform: uppercase; letter-spacing: 0.08em; color: var(--text-muted); margin-bottom: 16px; }
.footer-col a {
  display: block; color: var(--text-secondary); text-decoration: none;
  font-size: 0.875rem; margin-bottom: 10px; transition: var(--transition);
}
.footer-col a:hover { color: var(--text-primary); }
.footer-bottom {
  max-width: var(--max-width); margin: 40px auto 0; padding-top: 24px;
  border-top: 1px solid var(--border); display: flex; justify-content: space-between;
  align-items: center; font-size: 0.8rem; color: var(--text-muted);
}

/* Section */
.section { padding: 56px 24px; }
.section-inner { max-width: var(--max-width); margin: 0 auto; }
.section-label {
  font-size: 0.75rem; text-transform: uppercase; letter-spacing: 0.1em;
  color: var(--cta); margin-bottom: 12px; font-weight: 600;
}
.section-title { font-size: 2rem; font-weight: 700; letter-spacing: -0.02em; margin-bottom: 8px; }
.section-subtitle { color: var(--text-secondary); font-size: 1.05rem; max-width: 640px; margin-bottom: 32px; }

/* Hero */
.hero { padding: 80px 24px 64px; }
.hero-inner { max-width: var(--max-width); margin: 0 auto; text-align: center; }
.hero-badge {
  display: inline-flex; align-items: center; gap: 8px; background: rgba(0,207,139,0.1);
  border: 1px solid rgba(0,207,139,0.2); border-radius: 100px;
  padding: 4px 16px; font-size: 0.8rem; color: var(--cta); margin-bottom: 24px;
}
.hero-title {
  font-size: clamp(2.2rem, 5vw, 3.2rem); font-weight: 800; letter-spacing: -0.03em;
  line-height: 1.15; margin-bottom: 16px; max-width: 800px; margin-left: auto; margin-right: auto;
}
.hero-title span { color: var(--cta); }
.hero-subtitle {
  font-size: 1.1rem; color: var(--text-secondary); max-width: 700px;
  margin: 0 auto 40px; line-height: 1.7;
}
.hero-ctas { display: flex; flex-wrap: wrap; gap: 12px; justify-content: center; }
.btn { display: inline-flex; align-items: center; gap: 6px; padding: 10px 24px; border-radius: var(--radius-sm); font-size: 0.9rem; font-weight: 600; text-decoration: none; cursor: pointer; transition: var(--transition); border: none; }
.btn-primary { background: var(--cta); color: #000; }
.btn-primary:hover { background: var(--cta-hover); transform: translateY(-1px); box-shadow: 0 4px 12px rgba(0,207,139,0.25); }
.btn-secondary { background: rgba(255,255,255,0.06); color: var(--text-primary); border: 1px solid var(--border); }
.btn-secondary:hover { background: rgba(255,255,255,0.1); border-color: var(--border-light); }
.btn-accent { background: var(--accent); color: #fff; }
.btn-accent:hover { background: var(--accent-hover); transform: translateY(-1px); box-shadow: 0 4px 12px rgba(71,95,145,0.3); }

/* Cards */
.card {
  background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius-lg);
  padding: 28px; transition: var(--transition);
}
.card:hover { border-color: var(--border-light); background: var(--bg-card-hover); transform: translateY(-2px); box-shadow: var(--shadow-lg); }
.card-icon { width: 40px; height: 40px; border-radius: var(--radius-sm); margin-bottom: 16px; display: flex; align-items: center; justify-content: center; font-size: 1.2rem; }
.card-icon.blue { background: rgba(71,95,145,0.2); color: #7BA4E8; }
.card-icon.green { background: rgba(0,207,139,0.2); color: var(--cta); }
.card-icon.purple { background: rgba(139,92,246,0.2); color: #A78BFA; }
.card h3 { font-size: 1.05rem; font-weight: 600; margin-bottom: 8px; }
.card p { color: var(--text-secondary); font-size: 0.9rem; line-height: 1.6; margin-bottom: 16px; }
.card-link { color: var(--cta); font-size: 0.85rem; font-weight: 600; text-decoration: none; display: inline-flex; align-items: center; gap: 4px; transition: var(--transition); }
.card-link:hover { gap: 8px; color: var(--cta-hover); }

/* Grid layouts */
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 20px; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }

/* Product Cards (Home) */
.product-cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.product-card {
  background: linear-gradient(135deg, var(--bg-card), var(--bg-card-hover));
  border: 1px solid var(--border); border-radius: var(--radius-xl);
  padding: 36px 32px; transition: all 0.25s ease; position: relative; overflow: hidden;
}
.product-card::before {
  content: ''; position: absolute; top: 0; left: 0; right: 0; height: 3px;
  background: linear-gradient(90deg, var(--cta), var(--accent));
  transform: scaleX(0); transform-origin: left; transition: transform 0.3s ease;
}
.product-card:hover::before { transform: scaleX(1); }
.product-card:hover { border-color: var(--border-light); transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.product-card-icon {
  width: 48px; height: 48px; border-radius: var(--radius-md); margin-bottom: 20px;
  display: flex; align-items: center; justify-content: center; font-size: 1.4rem;
}
.product-card h3 { font-size: 1.25rem; font-weight: 700; margin-bottom: 8px; }
.product-card p { color: var(--text-secondary); font-size: 0.9rem; line-height: 1.6; margin-bottom: 20px; }

/* CLI Setup Section */
.cli-setup { background: var(--bg-secondary); border-top: 1px solid var(--border); border-bottom: 1px solid var(--border); }
.cli-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 40px; align-items: start; }
.cli-accordion { display: flex; flex-direction: column; gap: 2px; }
.accordion-item { border: 1px solid var(--border); border-radius: var(--radius-md); overflow: hidden; background: var(--bg-card); }
.accordion-header {
  width: 100%; background: none; border: none; color: var(--text-primary);
  padding: 16px 20px; font-size: 0.95rem; font-weight: 600; text-align: left;
  cursor: pointer; display: flex; align-items: center; justify-content: space-between;
  transition: var(--transition); font-family: var(--font-body);
}
.accordion-header:hover { background: rgba(255,255,255,0.03); }
.accordion-header .icon { transition: transform 0.25s ease; font-size: 0.7rem; color: var(--text-muted); }
.accordion-item.active .accordion-header .icon { transform: rotate(180deg); color: var(--cta); }
.accordion-item.active .accordion-header { color: var(--cta); }
.accordion-body { max-height: 0; overflow: hidden; transition: max-height 0.3s ease, padding 0.3s ease; }
.accordion-item.active .accordion-body { max-height: 300px; }
.accordion-body-inner { padding: 0 20px 20px; }
.accordion-step { display: flex; gap: 12px; margin-bottom: 14px; align-items: flex-start; }
.accordion-step-num {
  width: 22px; height: 22px; border-radius: 50%; background: var(--accent); color: #fff;
  display: flex; align-items: center; justify-content: center; font-size: 0.7rem; font-weight: 700;
  flex-shrink: 0; margin-top: 2px;
}
.accordion-step p { color: var(--text-secondary); font-size: 0.85rem; line-height: 1.6; }

/* Code blocks */
.code-block {
  background: var(--bg-code); border: 1px solid var(--border); border-radius: var(--radius-md); overflow: hidden;
}
.code-tabs { display: flex; border-bottom: 1px solid var(--border); background: rgba(0,0,0,0.2); }
.code-tab {
  padding: 10px 18px; font-size: 0.8rem; font-weight: 500; font-family: var(--font-body);
  background: none; border: none; color: var(--text-muted); cursor: pointer;
  border-bottom: 2px solid transparent; transition: var(--transition);
}
.code-tab:hover { color: var(--text-secondary); }
.code-tab.active { color: var(--cta); border-bottom-color: var(--cta); }
.code-tab-icon { margin-right: 4px; opacity: 0.6; }
.code-content { padding: 16px 20px; }
.code-content pre { margin: 0; font-family: var(--font-mono); font-size: 0.85rem; color: var(--text-primary); overflow-x: auto; white-space: pre-wrap; word-break: break-all; }
.code-content code { font-family: var(--font-mono); }
.code-copy {
  display: flex; align-items: center; gap: 6px; padding: 4px 10px; font-size: 0.75rem;
  background: rgba(255,255,255,0.05); border: 1px solid var(--border); border-radius: var(--radius-sm);
  color: var(--text-muted); cursor: pointer; transition: var(--transition); font-family: var(--font-body);
}
.code-copy:hover { color: var(--text-primary); border-color: var(--border-light); }
.code-header { display: flex; justify-content: space-between; align-items: center; padding: 0 0 12px; }

/* Launch CTA */
.launch-ctas { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }
.launch-card {
  background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius-lg);
  padding: 32px; transition: var(--transition);
}
.launch-card:hover { border-color: var(--border-light); box-shadow: var(--shadow-lg); }
.launch-card h4 { font-size: 1rem; font-weight: 600; margin-bottom: 8px; }
.launch-card p { color: var(--text-secondary); font-size: 0.88rem; margin-bottom: 16px; line-height: 1.6; }

/* Community */
.community-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; }
.community-card {
  background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius-md);
  padding: 24px; transition: var(--transition); text-decoration: none; display: block;
}
.community-card:hover { border-color: var(--border-light); background: var(--bg-card-hover); }
.community-card h4 { color: var(--text-primary); font-size: 0.95rem; font-weight: 600; margin-bottom: 4px; }
.community-card .arrow { color: var(--cta); font-size: 0.8rem; }

/* Docs Layout (Apps & Agents pages) */
.docs-layout { display: flex; min-height: calc(100vh - var(--topnav-height)); }
.sidebar {
  width: var(--sidebar-width); flex-shrink: 0;
  background: var(--bg-secondary); border-right: 1px solid var(--border);
  padding: 24px; position: sticky; top: var(--topnav-height);
  height: calc(100vh - var(--topnav-height)); overflow-y: auto;
  transition: width 0.25s ease, padding 0.25s ease, opacity 0.25s ease;
}
.sidebar.collapsed { width: 0; padding: 24px 0; opacity: 0; overflow: hidden; border-right: none; }
.sidebar-toggle {
  display: flex; align-items: center; gap: 8px; width: 100%; padding: 8px 12px;
  background: rgba(255,255,255,0.04); border: 1px solid var(--border); border-radius: var(--radius-sm);
  color: var(--text-secondary); cursor: pointer; font-size: 0.8rem; margin-bottom: 20px;
  transition: var(--transition); font-family: var(--font-body);
}
.sidebar-toggle:hover { background: rgba(255,255,255,0.08); color: var(--text-primary); }
.sidebar-toggle-icon { transition: transform 0.25s ease; }
.sidebar-nav { list-style: none; }
.sidebar-nav li { margin-bottom: 2px; }
.sidebar-nav a {
  display: block; padding: 8px 12px; color: var(--text-secondary); text-decoration: none;
  font-size: 0.85rem; border-radius: var(--radius-sm); transition: var(--transition);
}
.sidebar-nav a:hover, .sidebar-nav a.active { color: var(--text-primary); background: rgba(255,255,255,0.05); }
.sidebar-section-title { font-size: 0.7rem; text-transform: uppercase; letter-spacing: 0.08em; color: var(--text-muted); padding: 16px 12px 6px; }
.docs-content { flex: 1; min-width: 0; }
.docs-content .section-inner { max-width: 900px; }

/* Floating sidebar toggle when collapsed */
.sidebar-float-toggle {
  display: none; position: fixed; top: calc(var(--topnav-height) + 16px); left: 16px;
  z-index: 50; background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius-sm);
  padding: 8px 10px; color: var(--text-secondary); cursor: pointer; font-size: 0.85rem; transition: var(--transition);
}
.sidebar-float-toggle:hover { color: var(--text-primary); border-color: var(--border-light); }

/* Surfaces/Building Blocks/Use Cases Grid */
.items-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }
.item-card {
  background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius-md);
  padding: 24px; transition: var(--transition);
}
.item-card:hover { border-color: var(--border-light); background: var(--bg-card-hover); }
.item-card-icon { font-size: 1.2rem; margin-bottom: 12px; }
.item-card h4 { font-size: 0.95rem; font-weight: 600; margin-bottom: 6px; }
.item-card p { color: var(--text-secondary); font-size: 0.85rem; line-height: 1.5; }

/* Protocol Diagram */
.protocol-diagram {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; margin-top: 32px;
}
.protocol-actor {
  background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius-lg);
  padding: 28px 20px; text-align: center; transition: var(--transition);
}
.protocol-actor:hover { border-color: var(--border-light); transform: translateY(-2px); }
.protocol-actor-icon {
  width: 48px; height: 48px; border-radius: 50%; display: flex; align-items: center;
  justify-content: center; margin: 0 auto 14px; font-size: 1.3rem;
}
.protocol-actor h4 { font-size: 0.95rem; font-weight: 600; margin-bottom: 4px; }
.protocol-actor p { color: var(--text-secondary); font-size: 0.8rem; }

/* How it works */
.how-works-cards { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }

/* Feature highlight */
.feature-highlight {
  display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; margin-top: 24px;
}
.feature-card {
  background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius-md);
  padding: 24px; transition: var(--transition);
}
.feature-card:hover { border-color: var(--border-light); }
.feature-card h4 { font-size: 0.95rem; font-weight: 600; margin-bottom: 6px; }
.feature-card p { color: var(--text-secondary); font-size: 0.85rem; line-height: 1.5; }

/* Status badge */
.status-badge {
  display: inline-flex; align-items: center; gap: 6px; padding: 4px 12px;
  border-radius: 100px; font-size: 0.75rem; font-weight: 600;
}
.status-coming-soon { background: rgba(246,176,65,0.15); color: #F6B041; border: 1px solid rgba(246,176,65,0.25); }

/* Support categories */
.support-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; margin-top: 24px; }
.support-card {
  background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius-md);
  padding: 28px 24px; transition: var(--transition);
}
.support-card:hover { border-color: var(--border-light); }
.support-card h4 { font-size: 0.95rem; font-weight: 600; margin-bottom: 8px; }
.support-card p { color: var(--text-secondary); font-size: 0.85rem; line-height: 1.5; }

/* Responsive */
@media (max-width: 1024px) {
  .product-cards, .grid-3, .items-grid, .protocol-diagram { grid-template-columns: repeat(2, 1fr); }
  .community-grid, .support-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .cli-grid { grid-template-columns: 1fr; }
  .launch-ctas { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
  .topnav-links { display: none; }
  .mobile-menu-btn { display: block; }
  .topnav-search span:not(.sr-only) { display: none; }
  .product-cards, .grid-2, .grid-3, .items-grid, .protocol-diagram, .community-grid, .support-grid, .how-works-cards, .feature-highlight { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; gap: 8px; text-align: center; }
  .hero { padding: 48px 24px 40px; }
  .section { padding: 40px 20px; }
  .section-title { font-size: 1.6rem; }
  .sidebar { position: fixed; top: var(--topnav-height); left: 0; z-index: 30; height: calc(100vh - var(--topnav-height)); box-shadow: var(--shadow-lg); }
  .sidebar.collapsed { width: 0; padding: 24px 0; opacity: 0; }
  .sidebar-float-toggle { display: block; }
  .sidebar:not(.collapsed) + .sidebar-float-toggle { display: none; }
  .docs-content { margin-left: 0; }
  .topnav-actions .topnav-search { padding: 6px 8px; }
  .hero-ctas { flex-direction: column; align-items: center; }
  .hero-ctas .btn { width: 100%; justify-content: center; max-width: 320px; }
}

@media (min-width: 769px) {
  .sidebar-float-toggle { display: none !important; }
}

.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0,0,0,0); }

/* CommerceForge Dev Docs — Design System */
:root {
  --bg-primary: #0a0e17;
  --bg-secondary: #111620;
  --bg-card: #161b24;
  --bg-card-hover: #1c2330;
  --bg-code: #0d1117;
  --bg-surface: #131720;
  --accent: #475F91;
  --accent-hover: #5B78B0;
  --cta: #00CF8B;
  --cta-hover: #00E5A0;
  --text-primary: #E6EDF3;
  --text-secondary: #8B949E;
  --text-muted: #6E7681;
  --border: #21262D;
  --border-light: #30363D;
  --radius-sm: 6px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --shadow-card: 0 1px 3px rgba(0,0,0,0.3), 0 1px 2px rgba(0,0,0,0.2);
  --shadow-lg: 0 8px 24px rgba(0,0,0,0.4);
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', 'Cascadia Code', 'Consolas', monospace;
  --max-width: 1280px;
  --sidebar-width: 260px;
  --topnav-height: 56px;
  --transition: 200ms ease;
}

* { margin: 0; padding: 0; box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  font-family: var(--font-body);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

/* Top Navigation */
.topnav {
  position: sticky; top: 0; z-index: 100;
  background: rgba(10,14,23,0.85); backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
  height: var(--topnav-height);
  display: flex; align-items: center;
}
.topnav-inner {
  width: 100%; max-width: var(--max-width); margin: 0 auto;
  display: flex; align-items: center; justify-content: space-between;
  padding: 0 24px;
}
.topnav-logo {
  font-weight: 700; font-size: 1.1rem; color: var(--text-primary);
  text-decoration: none; letter-spacing: -0.01em;
  display: flex; align-items: center; gap: 8px;
}
.topnav-logo-icon { width: 28px; height: 28px; border-radius: 6px; background: var(--cta); }
.topnav-links { display: flex; align-items: center; gap: 4px; list-style: none; }
.topnav-links a {
  color: var(--text-secondary); text-decoration: none;
  padding: 6px 14px; border-radius: var(--radius-sm);
  font-size: 0.875rem; font-weight: 500; transition: var(--transition);
}
.topnav-links a:hover, .topnav-links a.active { color: var(--text-primary); background: rgba(255,255,255,0.05); }
.topnav-actions { display: flex; align-items: center; gap: 8px; }
.topnav-search {
  background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius-sm);
  padding: 6px 12px; color: var(--text-muted); font-size: 0.8rem;
  display: flex; align-items: center; gap: 8px; cursor: pointer; transition: var(--transition);
}
.topnav-search:hover { border-color: var(--border-light); color: var(--text-secondary); }
.topnav-search kbd {
  background: var(--bg-primary); border: 1px solid var(--border); border-radius: 3px;
  padding: 1px 5px; font-size: 0.7rem; font-family: var(--font-mono);
}
.dark-toggle {
  background: none; border: 1px solid var(--border); border-radius: var(--radius-sm);
  color: var(--text-secondary); cursor: pointer; padding: 6px 10px; font-size: 0.85rem; transition: var(--transition);
  display: flex; align-items: center; gap: 4px;
}
.dark-toggle:hover { border-color: var(--border-light); color: var(--text-primary); }
.topnav-login {
  background: var(--accent); color: #fff; border: none; border-radius: var(--radius-sm);
  padding: 7px 16px; font-size: 0.8rem; font-weight: 600; cursor: pointer; transition: var(--transition);
  text-decoration: none;
}
.topnav-login:hover { background: var(--accent-hover); }
.mobile-menu-btn {
  display: none; background: none; border: none; color: var(--text-primary); cursor: pointer;
  font-size: 1.3rem; padding: 4px;
}

/* Footer */
.footer {
  background: var(--bg-secondary); border-top: 1px solid var(--border);
  padding: 64px 24px 40px; margin-top: 80px;
}
.footer-grid {
  max-width: var(--max-width); margin: 0 auto;
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 40px;
}
.footer-col h4 { font-size: 0.75rem; text-transform: uppercase; letter-spacing: 0.08em; color: var(--text-muted); margin-bottom: 16px; }
.footer-col a {
  display: block; color: var(--text-secondary); text-decoration: none;
  font-size: 0.875rem; margin-bottom: 10px; transition: var(--transition);
}
.footer-col a:hover { color: var(--text-primary); }
.footer-bottom {
  max-width: var(--max-width); margin: 40px auto 0; padding-top: 24px;
  border-top: 1px solid var(--border); display: flex; justify-content: space-between;
  align-items: center; font-size: 0.8rem; color: var(--text-muted);
}

/* Section */
.section { padding: 56px 24px; }
.section-inner { max-width: var(--max-width); margin: 0 auto; }
.section-label {
  font-size: 0.75rem; text-transform: uppercase; letter-spacing: 0.1em;
  color: var(--cta); margin-bottom: 12px; font-weight: 600;
}
.section-title { font-size: 2rem; font-weight: 700; letter-spacing: -0.02em; margin-bottom: 8px; }
.section-subtitle { color: var(--text-secondary); font-size: 1.05rem; max-width: 640px; margin-bottom: 32px; }

/* Hero */
.hero { padding: 80px 24px 64px; }
.hero-inner { max-width: var(--max-width); margin: 0 auto; text-align: center; }
.hero-badge {
  display: inline-flex; align-items: center; gap: 8px; background: rgba(0,207,139,0.1);
  border: 1px solid rgba(0,207,139,0.2); border-radius: 100px;
  padding: 4px 16px; font-size: 0.8rem; color: var(--cta); margin-bottom: 24px;
}
.hero-title {
  font-size: clamp(2.2rem, 5vw, 3.2rem); font-weight: 800; letter-spacing: -0.03em;
  line-height: 1.15; margin-bottom: 16px; max-width: 800px; margin-left: auto; margin-right: auto;
}
.hero-title span { color: var(--cta); }
.hero-subtitle {
  font-size: 1.1rem; color: var(--text-secondary); max-width: 700px;
  margin: 0 auto 40px; line-height: 1.7;
}
.hero-ctas { display: flex; flex-wrap: wrap; gap: 12px; justify-content: center; }
.btn { display: inline-flex; align-items: center; gap: 6px; padding: 10px 24px; border-radius: var(--radius-sm); font-size: 0.9rem; font-weight: 600; text-decoration: none; cursor: pointer; transition: var(--transition); border: none; }
.btn-primary { background: var(--cta); color: #000; }
.btn-primary:hover { background: var(--cta-hover); transform: translateY(-1px); box-shadow: 0 4px 12px rgba(0,207,139,0.25); }
.btn-secondary { background: rgba(255,255,255,0.06); color: var(--text-primary); border: 1px solid var(--border); }
.btn-secondary:hover { background: rgba(255,255,255,0.1); border-color: var(--border-light); }
.btn-accent { background: var(--accent); color: #fff; }
.btn-accent:hover { background: var(--accent-hover); transform: translateY(-1px); box-shadow: 0 4px 12px rgba(71,95,145,0.3); }

/* Cards */
.card {
  background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius-lg);
  padding: 28px; transition: var(--transition);
}
.card:hover { border-color: var(--border-light); background: var(--bg-card-hover); transform: translateY(-2px); box-shadow: var(--shadow-lg); }
.card-icon { width: 40px; height: 40px; border-radius: var(--radius-sm); margin-bottom: 16px; display: flex; align-items: center; justify-content: center; font-size: 1.2rem; }
.card-icon.blue { background: rgba(71,95,145,0.2); color: #7BA4E8; }
.card-icon.green { background: rgba(0,207,139,0.2); color: var(--cta); }
.card-icon.purple { background: rgba(139,92,246,0.2); color: #A78BFA; }
.card h3 { font-size: 1.05rem; font-weight: 600; margin-bottom: 8px; }
.card p { color: var(--text-secondary); font-size: 0.9rem; line-height: 1.6; margin-bottom: 16px; }
.card-link { color: var(--cta); font-size: 0.85rem; font-weight: 600; text-decoration: none; display: inline-flex; align-items: center; gap: 4px; transition: var(--transition); }
.card-link:hover { gap: 8px; color: var(--cta-hover); }

/* Grid layouts */
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 20px; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }

/* Product Cards (Home) */
.product-cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.product-card {
  background: linear-gradient(135deg, var(--bg-card), var(--bg-card-hover));
  border: 1px solid var(--border); border-radius: var(--radius-xl);
  padding: 36px 32px; transition: all 0.25s ease; position: relative; overflow: hidden;
}
.product-card::before {
  content: ''; position: absolute; top: 0; left: 0; right: 0; height: 3px;
  background: linear-gradient(90deg, var(--cta), var(--accent));
  transform: scaleX(0); transform-origin: left; transition: transform 0.3s ease;
}
.product-card:hover::before { transform: scaleX(1); }
.product-card:hover { border-color: var(--border-light); transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.product-card-icon {
  width: 48px; height: 48px; border-radius: var(--radius-md); margin-bottom: 20px;
  display: flex; align-items: center; justify-content: center; font-size: 1.4rem;
}
.product-card h3 { font-size: 1.25rem; font-weight: 700; margin-bottom: 8px; }
.product-card p { color: var(--text-secondary); font-size: 0.9rem; line-height: 1.6; margin-bottom: 20px; }

/* CLI Setup Section */
.cli-setup { background: var(--bg-secondary); border-top: 1px solid var(--border); border-bottom: 1px solid var(--border); }
.cli-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 40px; align-items: start; }
.cli-accordion { display: flex; flex-direction: column; gap: 2px; }
.accordion-item { border: 1px solid var(--border); border-radius: var(--radius-md); overflow: hidden; background: var(--bg-card); }
.accordion-header {
  width: 100%; background: none; border: none; color: var(--text-primary);
  padding: 16px 20px; font-size: 0.95rem; font-weight: 600; text-align: left;
  cursor: pointer; display: flex; align-items: center; justify-content: space-between;
  transition: var(--transition); font-family: var(--font-body);
}
.accordion-header:hover { background: rgba(255,255,255,0.03); }
.accordion-header .icon { transition: transform 0.25s ease; font-size: 0.7rem; color: var(--text-muted); }
.accordion-item.active .accordion-header .icon { transform: rotate(180deg); color: var(--cta); }
.accordion-item.active .accordion-header { color: var(--cta); }
.accordion-body { max-height: 0; overflow: hidden; transition: max-height 0.3s ease, padding 0.3s ease; }
.accordion-item.active .accordion-body { max-height: 300px; }
.accordion-body-inner { padding: 0 20px 20px; }
.accordion-step { display: flex; gap: 12px; margin-bottom: 14px; align-items: flex-start; }
.accordion-step-num {
  width: 22px; height: 22px; border-radius: 50%; background: var(--accent); color: #fff;
  display: flex; align-items: center; justify-content: center; font-size: 0.7rem; font-weight: 700;
  flex-shrink: 0; margin-top: 2px;
}
.accordion-step p { color: var(--text-secondary); font-size: 0.85rem; line-height: 1.6; }

/* Code blocks */
.code-block {
  background: var(--bg-code); border: 1px solid var(--border); border-radius: var(--radius-md); overflow: hidden;
}
.code-tabs { display: flex; border-bottom: 1px solid var(--border); background: rgba(0,0,0,0.2); }
.code-tab {
  padding: 10px 18px; font-size: 0.8rem; font-weight: 500; font-family: var(--font-body);
  background: none; border: none; color: var(--text-muted); cursor: pointer;
  border-bottom: 2px solid transparent; transition: var(--transition);
}
.code-tab:hover { color: var(--text-secondary); }
.code-tab.active { color: var(--cta); border-bottom-color: var(--cta); }
.code-tab-icon { margin-right: 4px; opacity: 0.6; }
.code-content { padding: 16px 20px; }
.code-content pre { margin: 0; font-family: var(--font-mono); font-size: 0.85rem; color: var(--text-primary); overflow-x: auto; white-space: pre-wrap; word-break: break-all; }
.code-content code { font-family: var(--font-mono); }
.code-copy {
  display: flex; align-items: center; gap: 6px; padding: 4px 10px; font-size: 0.75rem;
  background: rgba(255,255,255,0.05); border: 1px solid var(--border); border-radius: var(--radius-sm);
  color: var(--text-muted); cursor: pointer; transition: var(--transition); font-family: var(--font-body);
}
.code-copy:hover { color: var(--text-primary); border-color: var(--border-light); }
.code-header { display: flex; justify-content: space-between; align-items: center; padding: 0 0 12px; }

/* Launch CTA */
.launch-ctas { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }
.launch-card {
  background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius-lg);
  padding: 32px; transition: var(--transition);
}
.launch-card:hover { border-color: var(--border-light); box-shadow: var(--shadow-lg); }
.launch-card h4 { font-size: 1rem; font-weight: 600; margin-bottom: 8px; }
.launch-card p { color: var(--text-secondary); font-size: 0.88rem; margin-bottom: 16px; line-height: 1.6; }

/* Community */
.community-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; }
.community-card {
  background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius-md);
  padding: 24px; transition: var(--transition); text-decoration: none; display: block;
}
.community-card:hover { border-color: var(--border-light); background: var(--bg-card-hover); }
.community-card h4 { color: var(--text-primary); font-size: 0.95rem; font-weight: 600; margin-bottom: 4px; }
.community-card .arrow { color: var(--cta); font-size: 0.8rem; }

/* Docs Layout (Apps & Agents pages) */
.docs-layout { display: flex; min-height: calc(100vh - var(--topnav-height)); }
.sidebar {
  width: var(--sidebar-width); flex-shrink: 0;
  background: var(--bg-secondary); border-right: 1px solid var(--border);
  padding: 24px; position: sticky; top: var(--topnav-height);
  height: calc(100vh - var(--topnav-height)); overflow-y: auto;
  transition: width 0.25s ease, padding 0.25s ease, opacity 0.25s ease;
}
.sidebar.collapsed { width: 0; padding: 24px 0; opacity: 0; overflow: hidden; border-right: none; }
.sidebar-toggle {
  display: flex; align-items: center; gap: 8px; width: 100%; padding: 8px 12px;
  background: rgba(255,255,255,0.04); border: 1px solid var(--border); border-radius: var(--radius-sm);
  color: var(--text-secondary); cursor: pointer; font-size: 0.8rem; margin-bottom: 20px;
  transition: var(--transition); font-family: var(--font-body);
}
.sidebar-toggle:hover { background: rgba(255,255,255,0.08); color: var(--text-primary); }
.sidebar-toggle-icon { transition: transform 0.25s ease; }
.sidebar-nav { list-style: none; }
.sidebar-nav li { margin-bottom: 2px; }
.sidebar-nav a {
  display: block; padding: 8px 12px; color: var(--text-secondary); text-decoration: none;
  font-size: 0.85rem; border-radius: var(--radius-sm); transition: var(--transition);
}
.sidebar-nav a:hover, .sidebar-nav a.active { color: var(--text-primary); background: rgba(255,255,255,0.05); }
.sidebar-section-title { font-size: 0.7rem; text-transform: uppercase; letter-spacing: 0.08em; color: var(--text-muted); padding: 16px 12px 6px; }
.docs-content { flex: 1; min-width: 0; }
.docs-content .section-inner { max-width: 900px; }

/* Floating sidebar toggle when collapsed */
.sidebar-float-toggle {
  display: none; position: fixed; top: calc(var(--topnav-height) + 16px); left: 16px;
  z-index: 50; background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius-sm);
  padding: 8px 10px; color: var(--text-secondary); cursor: pointer; font-size: 0.85rem; transition: var(--transition);
}
.sidebar-float-toggle:hover { color: var(--text-primary); border-color: var(--border-light); }

/* Surfaces/Building Blocks/Use Cases Grid */
.items-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }
.item-card {
  background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius-md);
  padding: 24px; transition: var(--transition);
}
.item-card:hover { border-color: var(--border-light); background: var(--bg-card-hover); }
.item-card-icon { font-size: 1.2rem; margin-bottom: 12px; }
.item-card h4 { font-size: 0.95rem; font-weight: 600; margin-bottom: 6px; }
.item-card p { color: var(--text-secondary); font-size: 0.85rem; line-height: 1.5; }

/* Protocol Diagram */
.protocol-diagram {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; margin-top: 32px;
}
.protocol-actor {
  background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius-lg);
  padding: 28px 20px; text-align: center; transition: var(--transition);
}
.protocol-actor:hover { border-color: var(--border-light); transform: translateY(-2px); }
.protocol-actor-icon {
  width: 48px; height: 48px; border-radius: 50%; display: flex; align-items: center;
  justify-content: center; margin: 0 auto 14px; font-size: 1.3rem;
}
.protocol-actor h4 { font-size: 0.95rem; font-weight: 600; margin-bottom: 4px; }
.protocol-actor p { color: var(--text-secondary); font-size: 0.8rem; }

/* How it works */
.how-works-cards { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }

/* Feature highlight */
.feature-highlight {
  display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; margin-top: 24px;
}
.feature-card {
  background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius-md);
  padding: 24px; transition: var(--transition);
}
.feature-card:hover { border-color: var(--border-light); }
.feature-card h4 { font-size: 0.95rem; font-weight: 600; margin-bottom: 6px; }
.feature-card p { color: var(--text-secondary); font-size: 0.85rem; line-height: 1.5; }

/* Status badge */
.status-badge {
  display: inline-flex; align-items: center; gap: 6px; padding: 4px 12px;
  border-radius: 100px; font-size: 0.75rem; font-weight: 600;
}
.status-coming-soon { background: rgba(246,176,65,0.15); color: #F6B041; border: 1px solid rgba(246,176,65,0.25); }

/* Support categories */
.support-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; margin-top: 24px; }
.support-card {
  background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius-md);
  padding: 28px 24px; transition: var(--transition);
}
.support-card:hover { border-color: var(--border-light); }
.support-card h4 { font-size: 0.95rem; font-weight: 600; margin-bottom: 8px; }
.support-card p { color: var(--text-secondary); font-size: 0.85rem; line-height: 1.5; }

/* Responsive */
@media (max-width: 1024px) {
  .product-cards, .grid-3, .items-grid, .protocol-diagram { grid-template-columns: repeat(2, 1fr); }
  .community-grid, .support-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .cli-grid { grid-template-columns: 1fr; }
  .launch-ctas { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
  .topnav-links { display: none; }
  .mobile-menu-btn { display: block; }
  .topnav-search span:not(.sr-only) { display: none; }
  .product-cards, .grid-2, .grid-3, .items-grid, .protocol-diagram, .community-grid, .support-grid, .how-works-cards, .feature-highlight { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; gap: 8px; text-align: center; }
  .hero { padding: 48px 24px 40px; }
  .section { padding: 40px 20px; }
  .section-title { font-size: 1.6rem; }
  .sidebar { position: fixed; top: var(--topnav-height); left: 0; z-index: 30; height: calc(100vh - var(--topnav-height)); box-shadow: var(--shadow-lg); }
  .sidebar.collapsed { width: 0; padding: 24px 0; opacity: 0; }
  .sidebar-float-toggle { display: block; }
  .sidebar:not(.collapsed) + .sidebar-float-toggle { display: none; }
  .docs-content { margin-left: 0; }
  .topnav-actions .topnav-search { padding: 6px 8px; }
  .hero-ctas { flex-direction: column; align-items: center; }
  .hero-ctas .btn { width: 100%; justify-content: center; max-width: 320px; }
}

@media (min-width: 769px) {
  .sidebar-float-toggle { display: none !important; }
}

.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0,0,0,0); }

